="mb-3"><h5 class="mb-1">تعریف کالای جدید برای برگشت سازه‌حساب</h5><div class="sr-muted small">کالا و تنوع‌ها پس از ثبت نهایی سند ساخته می‌شوند. تصویر موقت در این مودال پشتیبانی نمی‌شود تا فایل بدون سند در Public رها نشود.</div></div><div class="np-grid"><div class="card-soft"><div class="section-head">اطلاعات پایه و دسته‌بندی</div><label class="form-label">نام کالا <span class="text-danger">*</span></label><input class="form-control form-control-sm mb-2 np-field" id="npName"><div class="row g-2"><div class="col-md-6"><label class="form-label">واحد پیش‌فرض</label><input class="form-control form-control-sm np-field" id="npUnit" value="عدد"></div><div class="col-md-6"><label class="form-label">قابل فروش</label><select class="form-select form-select-sm np-field" id="npSales"><option value="1">فعال</option><option value="0">قابل بازبینی/غیرفعال</option></select></div></div><div class="tree-box mt-3"><div class="d-flex justify-content-between align-items-center mb-2"><strong>دسته‌بندی درختی</strong><button class="btn btn-sm btn-outline-primary" type="button" id="npQuickCategory">+ افزودن دسته‌بندی جدید</button></div><div class="row g-2" id="npCategoryLevels"></div><div class="np-field-error" id="npCategoryError"></div><div class="mt-2"><span id="npCategoryBreadcrumb" class="tree-breadcrumb">دسته‌بندی انتخاب نشده است</span></div></div><div class="preview-box mt-3"><div class="small sr-muted mb-2" id="npCodeHint">پس از انتخاب دسته‌بندی، کد کالا نمایش داده می‌شود.</div><div class="row g-2"><div class="col"><div class="mini-stat">شماره ترتیبی<br><strong id="npSeqPreview">{{ str_pad((string)((int)\App\Models\Product::max('id') + 1), 4, '0', STR_PAD_LEFT) }}</strong></div></div><div class="col"><div class="mini-stat">کد کالا<br><strong id="npProductCodePreview">—</strong></div></div><div class="col"><div class="mini-stat">الگوی تنوع<br><strong id="npVariantCodePreview">—</strong></div></div></div></div></div><div class="card-soft model-picker"><div class="section-head">مدل‌لیست</div><div class="form-check form-switch mb-2"><input class="form-check-input np-field" type="checkbox" id="npUseModels"><label class="form-check-label fw-bold" for="npUseModels">این کالا مدل‌لیست دارد</label></div><div id="npModelPanel" class="picker-panel d-none"><label class="form-label">گروه برند</label><select class="form-select form-select-sm mb-2 np-field" id="npModelBrand"><option value="">انتخاب برند</option></select><div class="input-group input-group-sm mb-2"><input class="form-control np-field" id="npModelSearch" placeholder="جستجو با نام یا کد"><button class="btn btn-outline-primary" type="button" id="npQuickModel">+ افزودن مدل جدید</button></div><div class="d-flex gap-2 mb-2"><button type="button" class="btn btn-sm btn-outline-secondary" id="npSelectFilteredModels">انتخاب همه نتایج</button><button type="button" class="btn btn-sm btn-outline-danger" id="npClearModels">پاک‌کردن همه</button><span class="small sr-muted me-auto"><span id="npSelectedModelCount">0</span> مدل انتخاب‌شده</span></div><div id="npModelTags" class="d-flex flex-wrap gap-1 mb-2"></div><div class="picker-list" id="npModelList"></div></div></div><div class="card-soft np-design-card"><div class="section-head">طرح‌بندی</div><div class="form-check form-switch mb-2"><input class="form-check-input np-field" type="checkbox" id="npUseDesigns"><label class="form-check-label fw-bold" for="npUseDesigns">این کالا طرح‌بندی دارد</label></div><div id="npDesignPanel" class="d-none"><label class="form-label">تعداد طرح</label><input type="number" min="1" max="99" class="form-control form-control-sm mb-2 np-field" id="npDesignCount" value="1"><div id="npDesignRows" class="np-design-grid"></div><div class="np-field-error" id="npDesignError"></div></div></div><div class="card-soft"><div class="section-head">قیمت‌ها (ریال)</div><div class="np-price-grid"><div><label class="form-label">قیمت خرید فعلی</label><input type="text" inputmode="numeric" class="form-control form-control-sm np-field np-money" id="npPurchase" autocomplete="off"><div class="np-field-error" data-price-error="npPurchase"></div></div><div><label class="form-label">قیمت فروش فعلی</label><input type="text" inputmode="numeric" class="form-control form-control-sm np-field np-money" id="npSell" autocomplete="off"><div class="np-field-error" data-price-error="npSell"></div></div><div><label class="form-label">قیمت برگشتی پیش‌فرض مشتری</label><input type="text" inputmode="numeric" class="form-control form-control-sm np-field np-money" id="npRefund" autocomplete="off"><div class="np-field-error" data-price-error="npRefund"></div></div></div><div class="preview-box mt-3"><div class="np-summary-strip"><div><span>کل: </span><strong id="npTotalVariants">1</strong></div><div><span>انتخاب‌شده: </span><strong id="npPickedVariants">1</strong></div><div><span>حذف‌شده: </span><strong id="npUnpickedVariants">0</strong></div></div></div></div><div class="card-soft mt-3 sr-variant-preview"><div class="section-head">پیش‌نمایش تنوع‌های قابل ساخت</div><div class="sr-variant-preview__viewport"><div class="sr-variant-preview__header"><div>انتخاب</div><div>نام تنوع</div><div>مدل</div><div>طرح</div><div>کد نمونه</div><div>خرید</div><div>فروش</div><div>برگشتی</div></div><div id="npVariantPreview"></div></div><div class="np-field-error" id="npVariantError"></div><div class="text-danger small d-none" id="npErrors"></div></div></div>@endcan</div></div></div><div class="modal-footer"><div class="sr-modal__footer"><span class="small sr-muted">انتخاب‌شده: <strong id="npFooterSelected">0</strong> | مبلغ برگشتی پیش‌فرض: <strong id="npFooterRefund">0</strong> ریال</span><div class="sr-modal__footer-actions"><button class="btn btn-outline-secondary btn-sm" type="button" data-bs-dismiss="modal">انصراف</button>@can('sales_returns.create_product')<button class="btn btn-primary btn-sm" type="button" id="addNewProductRow" disabled>افزودن تنوع‌های انتخاب‌شده</button>@endcan</div></div></div></div></div>
<script>
window.salesReturnRoutes = @json($salesReturnRoutes);
window.salesReturnInitial = {items:@json($initialItems), sourceType:@json(old('source_type', $document?->source_type ?? 'internal_invoice')), customerId:@json(old('customer_id', $document?->customer_id)), invoiceId:@json(old('invoice_id', $document?->invoice_id)), warehouses:@json($warehouses->map(fn($w)=>['id'=>$w->id,'name'=>$w->name,'type'=>$w->type])->values()), categories:@json($categories->values()), modelLists:@json($modelLists->values())};
</script>
<script>
(() => {
const routes=window.salesReturnRoutes, init=window.salesReturnInitial;
const state={type:init.sourceType||'internal_invoice',customer:{id:init.customerId||null,name:'',mobile:'',code:''},invoice:null,externalInvoiceDate:document.getElementById('externalInvoiceDate')?.value||'',internalItems:[],sazehItems:[],newProducts:[],newProduct:{prices:{purchase:null,sell:null,refund:null}},selectedCategories:[],selectedProducts:{},selectedVariants:new Map(),defaultDestinationWarehouseId:document.getElementById('defaultWarehouse').value,summary:{},items:init.items||[]};
let customerAbort, invoiceAbort, customerRequest=0, invoiceRequest=0, customerActive=-1, productAbort, categoryProductAbort, customerTimer, productTimer;
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const faDigits='۰۱۲۳۴۵۶۷۸۹', enDigits='0123456789';
const toPersianDigits=v=>String(v??'').replace(/[0-9]/g,d=>faDigits[d]);
const toEnglishDigits=v=>String(v??'').replace(/[۰-۹]/g,d=>String(faDigits.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
const sanitizeMoneyInput=v=>toEnglishDigits(v).replace(/(ریال|تومان)/g,'').replace(/[,،.\s]/g,'').replace(/[^0-9]/g,'');
const moneyToInteger=v=>{const clean=sanitizeMoneyInput(v);return clean===''?null:parseInt(clean,10)};
const rawNumber=v=>moneyToInteger(v)??0;
const fmt=n=>{const value=typeof n==='number'?n:moneyToInteger(n);return value===null?'':value.toLocaleString('fa-IR')};
const moneyText=n=>(fmt(n)||'۰')+' ریال';
const fmtDate=d=>formatJalaliDate(d)||'—';
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const whName=id=>(init.warehouses.find(w=>String(w.id)===String(id))||{}).name||'—';
function gregorianToJalali(gy,gm,gd){const g_d_m=[0,31,59,90,120,151,181,212,243,273,304,334];let jy=(gy<=1600)?0:979;gy-=(gy<=1600)?621:1600;const gy2=(gm>2)?gy+1:gy;let days=(365*gy)+Math.floor((gy2+3)/4)-Math.floor((gy2+99)/100)+Math.floor((gy2+399)/400)-80+gd+g_d_m[gm-1];jy+=33*Math.floor(days/12053);days%=12053;jy+=4*Math.floor(days/1461);days%=1461;if(days>365){jy+=Math.floor((days-1)/365);days=(days-1)%365}const jm=(days<186)?1+Math.floor(days/31):7+Math.floor((days-186)/30);const jd=1+((days<186)?(days%31):((days-186)%30));return [jy,jm,jd]}
function formatJalaliDate(value){if(!value)return'';const m=toEnglishDigits(value).match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);if(!m)return toPersianDigits(value);const [jy,jm,jd]=gregorianToJalali(+m[1],+m[2],+m[3]);return toPersianDigits(`${jy}/${String(jm).padStart(2,'0')}/${String(jd).padStart(2,'0')}`)}
function jalaliToGregorian(jy,jm,jd){jy=Number(jy);jm=Number(jm);jd=Number(jd);jy+=(jy<100)?1400:0;let gy=jy<=979?621:1600;let y=jy<=979?jy:jy-979;let days=365*y+Math.floor(y/33)*8+Math.floor(((y%33)+3)/4)+78+jd+(jm<7?(jm-1)*31:(jm-7)*30+186);gy+=400*Math.floor(days/146097);days%=146097;if(days>36524){gy+=100*Math.floor(--days/36524);days%=36524;if(days>=365)days++}gy+=4*Math.floor(days/1461);days%=1461;if(days>365){gy+=Math.floor((days-1)/365);days=(days-1)%365}let gd=days+1;const sal=[0,31,((gy%4===0&&gy%100!==0)||gy%400===0)?29:28,31,30,31,30,31,31,30,31,30,31];let gm=1;while(gm<=12&&gd>sal[gm]){gd-=sal[gm];gm++}return [gy,gm,gd]}
function normalizeJalaliDateInput(v){const normalized=toEnglishDigits(v).trim().replace(/\s+/g,'').replace(/-/g,'/');if(normalized==='')return'';const m=normalized.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/);if(!m)return null;const jy=+m[1],jm=+m[2],jd=+m[3];if(jm<1||jm>12||jd<1||jd>31)return null;const [gy,gm,gd]=jalaliToGregorian(jy,jm,jd);return `${gy}-${String(gm).padStart(2,'0')}-${String(gd).padStart(2,'0')}`}
function syncExternalDateDisplay(){const raw=$('#externalInvoiceDate')?.value;const fa=$('#externalInvoiceDateFa');if(fa&&raw)fa.value=formatJalaliDate(raw)}
function syncExternalDateFromVisible(showError=false){const fa=$('#externalInvoiceDateFa'), hidden=$('#externalInvoiceDate'), err=$('#externalInvoiceDateError');if(!fa||!hidden)return true;const parsed=normalizeJalaliDateInput(fa.value);if(parsed===null){if(showError&&err)err.textContent='تاریخ را به‌شکل ۱۴۰۵/۰۴/۲۲ وارد کنید.';return false}hidden.value=parsed;state.externalInvoiceDate=parsed;if(err)err.textContent='';return true}
function initSazehInvoiceDatePicker(){const input=$('#externalInvoiceDateFa');if(!input)return;input.disabled=state.type!=='sazeh_hesab';input.readOnly=false;if(input.dataset.datepickerInitialized==='1')return;input.dataset.datepickerInitialized='1';if(window.jalaliDatepicker){window.jalaliDatepicker.startWatch({selector:'#externalInvoiceDateFa',persianDigits:true,zIndex:3000});input.addEventListener('jdp:change',()=>syncExternalDateFromVisible(false));}}

function syncSource(){state.type=$('#sourceTypeInput').value=state.type;$$('[data-source-choice]').forEach(el=>el.classList.toggle('active',el.dataset.sourceChoice===state.type));$$('[name=source_choice]').forEach(r=>r.checked=r.value===state.type);$$('.sazeh-only').forEach(el=>el.classList.toggle('d-none',state.type!=='sazeh_hesab'));$$('.internal-only,.internal-col').forEach(el=>el.classList.toggle('d-none',state.type==='sazeh_hesab'));initSazehInvoiceDatePicker();if(state.type==='internal_invoice'&&state.customer.id)loadCustomerInvoices(state.customer.id);renderItems();}
function setSource(type){if(type===state.type)return;if(state.items.length&&!confirm('با تغییر نوع برگشت، اقلام فعلی پاک می‌شوند. ادامه می‌دهید؟')){syncSource();return}state.type=type;state.invoice=null;$('#invoiceId').value='';state.items=[];if(type!=='internal_invoice')resetInvoiceSelect('فاکتور داخلی فقط در نوع فاکتور داخلی بارگذاری می‌شود.', true);syncSource();}
function hiddenInputs(it,i){const parts=[];const input=(name,v)=>parts.push(`<input type="hidden" name="${name}" value="${esc(v)}">`);const h=(k,v)=>input(`items[${i}][${k}]`,v);const nested=(base,val)=>{if(Array.isArray(val)){val.forEach((v,idx)=>nested(`${base}[${idx}]`,v));return}if(val&&typeof val==='object'){Object.entries(val).forEach(([k,v])=>nested(`${base}[${k}]`,v));return}input(base,val??'')};h('item_source',it.item_source);h('invoice_item_id',it.invoice_item_id||'');h('product_variant_id',it.product_variant_id||'');h('return_quantity',it.return_quantity||1);h('refund_unit_price',it.refund_unit_price||0);h('purchase_price',it.purchase_price||'');h('sell_price',it.sell_price||'');if(it.new_product_payload)nested(`items[${i}][new_product_payload]`,it.new_product_payload);return parts.join('')}
function rowName(it){return `${it.product_name||it.new_product_payload?.product_name||'—'} / ${it.variant_name||it.new_product_payload?.variant_name||'—'}`}
function renderItems(){const tb=$('#itemsTable tbody');tb.innerHTML='';$('#mobileItems').innerHTML='';state.items.forEach((it,i)=>{const max=state.type==='internal_invoice'?(it.returnable||1):999999;it.return_quantity=Math.max(1,Math.min(Number(it.return_quantity||1),max));it.refund_amount=it.return_quantity*Number(it.refund_unit_price||0);const tr=document.createElement('tr');tr.innerHTML=`<td>${hiddenInputs(it,i)}<strong>${esc(rowName(it))}</strong><div class="small sr-muted">${it.item_source==='new_product'?'کالای جدید؛ ساخت در ثبت نهایی':it.item_source==='existing_product'?'کالای موجود':'آیتم فاکتور'}</div></td><td>${esc(it.sku||it.barcode||it.new_product_payload?.sku||'—')}</td><td class="internal-col">${it.sold_quantity??'—'}</td><td class="internal-col">${it.previously_returned??'—'}</td><td class="internal-col">${it.returnable??'—'}</td><td><input class="form-control form-control-sm qty" data-i="${i}" type="number" min="1" max="${max}" value="${it.return_quantity}"></td><td>${state.type==='internal_invoice'?fmt(it.refund_unit_price):`<input class="form-control form-control-sm price" data-i="${i}" type="number" min="1" value="${it.refund_unit_price||0}">`}</td><td>${fmt(it.refund_amount)}</td><td><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></td>`;tb.appendChild(tr);$('#mobileItems').insertAdjacentHTML('beforeend',`<div class="border rounded p-2 mb-2"><div class="d-flex justify-content-between"><strong>${esc(rowName(it))}</strong><button class="btn btn-sm btn-outline-danger rm" data-i="${i}" type="button">حذف</button></div><div class="small sr-muted">تعداد: ${fmt(it.return_quantity)} | مبلغ: ${fmt(it.refund_amount)}</div></div>`)});$$('.internal-col').forEach(el=>el.classList.toggle('d-none',state.type==='sazeh_hesab'));summary();}
function summary(){const qty=state.items.reduce((s,i)=>s+Number(i.return_quantity||0),0),amount=state.items.reduce((s,i)=>s+Number(i.refund_amount||0),0);$('[data-sum=rows]').textContent=state.items.length;$('[data-sum=qty]').textContent=fmt(qty);$('[data-sum=amount]').textContent=fmt(amount);$('[data-sum=warehouses]').textContent=whName(state.defaultDestinationWarehouseId)||'—'}
function positionCustomerDropdown(){const box=$('#customerResults'), input=$('#customerSearch');if(!box||!input||box.classList.contains('d-none'))return;const r=input.getBoundingClientRect();const w=Math.min(r.width, window.innerWidth-16);box.style.width=w+'px';box.style.top=(r.bottom+6)+'px';box.style.left=Math.max(8, Math.min(r.left, window.innerWidth-w-8))+'px'}
function openCustomerDropdown(){const box=$('#customerResults');if(box.parentElement!==document.body)document.body.appendChild(box);box.classList.remove('d-none');$('#customerSearch')?.setAttribute('aria-expanded','true');positionCustomerDropdown()}
function closeCustomerDropdown(){const box=$('#customerResults');box?.classList.add('d-none');$('#customerSearch')?.setAttribute('aria-expanded','false')}
function renderCustomerStatus(html){$('#customerResults').innerHTML=html;openCustomerDropdown();customerActive=-1}
async function searchCustomers(q=''){q=(q||'').trim();if(customerAbort)customerAbort.abort();const req=++customerRequest;customerAbort=new AbortController();renderCustomerStatus(q.length<2?'<div class="p-2 sr-muted">نام، موبایل یا کد مشتری را جستجو کنید.</div>':'<div class="p-2 sr-muted">در حال دریافت مشتریان...</div>');try{const url=routes.customersSearch+(q.length>=2?('?q='+encodeURIComponent(q)):'');const r=await fetch(url,{signal:customerAbort.signal});if(req!==customerRequest)return;const data=await r.json();const rows=data.data||data.results||[];renderCustomerStatus(rows.length?rows.map(c=>`<div class="sr-result" role="option" tabindex="0" data-id="${c.id}" data-name="${esc(c.name||c.text)}" data-mobile="${esc(c.mobile||'')}" data-code="${esc(c.customer_code||c.code||'')}"><strong>${esc(c.name||c.text)}</strong><div class="small sr-muted">${esc(toPersianDigits(c.mobile||'بدون موبایل'))} | کد: ${esc(toPersianDigits(c.customer_code||c.code||c.id))}</div></div>`).join(''):'<div class="p-2 sr-muted">مشتری‌ای پیدا نشد.</div>')}catch(e){if(e.name!=='AbortError')renderCustomerStatus('<div class="p-2 text-danger">دریافت مشتریان با خطا مواجه شد.</div>')}}
function renderSelectedCustomer(){const label=$('#selectedCustomerLabel');if(!label)return;if(!state.customer.id){label.textContent='نام، موبایل یا کد مشتری را جستجو کنید.';return}label.innerHTML=`<span><strong>${esc(state.customer.name||'—')}</strong><br><span class="sr-muted">${esc(toPersianDigits(state.customer.mobile||'بدون موبایل'))} — کد: ${esc(toPersianDigits(state.customer.code||state.customer.id))}</span></span><button type="button" class="btn btn-link btn-sm p-0" id="clearCustomer">تغییر/حذف</button>`}
function resetInvoiceSelect(message='ابتدا مشتری را انتخاب کنید', disabled=true){const select=$('#invoiceSelect');if(!select)return;select.disabled=disabled;select.innerHTML=`<option value="">${esc(message)}</option>`;$('#invoiceSummary')&&($('#invoiceSummary').textContent='');$('#invoiceId').value='';state.invoice=null}
function setSelectedCustomer(customer){const id=Number(customer?.id||0);if(!id){state.customer={id:null,name:'',mobile:'',code:''};$('#customerId').value='';$('#customerSearch').value='';state.items=[];renderItems();renderSelectedCustomer();resetInvoiceSelect();return}const changed=String(state.customer.id||'')!==String(id);state.customer={id:String(id),name:customer.name||customer.text||'',mobile:customer.mobile||'',code:customer.code||customer.customer_code||String(id)};$('#customerId').value=state.customer.id;$('#customerSearch').value=state.customer.name;renderSelectedCustomer();closeCustomerDropdown();if(changed){state.items=[];renderItems();resetInvoiceSelect('در حال دریافت فاکتورها...', true)}if(state.type==='internal_invoice')loadCustomerInvoices(state.customer.id);}
function selectCustomer(el){setSelectedCustomer({id:el.dataset.id,name:el.dataset.name,mobile:el.dataset.mobile,code:el.dataset.code})}
async function loadCustomerInvoices(customerId){customerId=String(customerId||state.customer.id||'');if(!customerId){resetInvoiceSelect();return}if(state.type!=='internal_invoice')return;if(invoiceAbort)invoiceAbort.abort();const req=++invoiceRequest;invoiceAbort=new AbortController();resetInvoiceSelect('در حال دریافت فاکتورها...', true);try{const r=await fetch(routes.customerInvoices.replace('__CUSTOMER__',encodeURIComponent(customerId)),{signal:invoiceAbort.signal});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(req!==invoiceRequest||String(state.customer.id)!==String(customerId))return;const invoices=Array.isArray(data.invoices)?data.invoices:(Array.isArray(data.data)?data.data:[]);const select=$('#invoiceSelect');select.disabled=false;if(!invoices.length){select.innerHTML='<option value="">فاکتور مجاز برای این مشتری پیدا نشد</option>';return}select.innerHTML='<option value="">انتخاب فاکتور</option>'+invoices.map(inv=>{const number=inv.number||inv.uuid||inv.id;const dateFa=inv.invoice_date_fa||inv.date_fa||fmtDate(inv.invoice_date||inv.date);const total=inv.total??inv.amount??0;const items=inv.items_count??0;const status=inv.status_label||inv.status||'';const summary=`فاکتور ${toPersianDigits(number)} | ${dateFa} | ${moneyText(total)} | ${toPersianDigits(items)} قلم | ${status}`;return `<option value="${esc(inv.id)}" data-summary="${esc(summary)}">فاکتور ${esc(toPersianDigits(number))} | ${esc(dateFa)} | ${moneyText(total)} | ${esc(status)} | ${toPersianDigits(items)} قلم</option>`}).join('');if(init.invoiceId&&String(state.customer.id)===String(customerId))select.value=init.invoiceId;renderInvoiceSummary()}catch(e){if(e.name==='AbortError')return;console.error('loadCustomerInvoices failed',e);resetInvoiceSelect('دریافت فاکتورها با خطا مواجه شد', true)}}
async function loadInvoices(){return loadCustomerInvoices(state.customer.id||$('#customerId').value)}
async function loadInvoiceItems(){const inv=$('#invoiceId').value;if(!inv){alert('ابتدا فاکتور را انتخاب کنید.');return}const r=await fetch(routes.invoiceItems.replace('__INVOICE__',inv)+'?customer_id='+encodeURIComponent($('#customerId').value));if(!r.ok){alert((await r.json()).message||'خطا');return}const data=await r.json();$('#invoiceItemsBody').innerHTML=(data.items||[]).map(it=>`<tr class="${it.disabled?'table-secondary':''}" data-text="${esc((it.product_name||'')+' '+(it.variant_name||'')+' '+(it.sku||''))}"><td><input type="checkbox" class="invoice-pick" ${it.disabled||state.items.some(x=>x.invoice_item_id===it.invoice_item_id)?'disabled':''} data-item='${esc(JSON.stringify(it))}'></td><td>${esc(it.product_name||'—')}</td><td>${esc(it.variant_name||'—')}</td><td>${esc(it.sku||it.barcode||'—')}</td><td>${fmt(it.quantity)}</td><td>${fmt(it.previously_returned)}</td><td>${fmt(it.returnable)}</td><td>${fmt(it.unit_price)}</td></tr>`).join('')}
async function loadCategories(parentId=null){const url=routes.categories+(parentId?('?parent_id='+parentId):'');const r=await fetch(url);const data=await r.json();$('#categoryResults').innerHTML=(data.data||[]).map(c=>`<button type="button" class="list-group-item list-group-item-action cat-pick" data-id="${c.id}" data-name="${esc(c.name)}" data-code="${esc(c.code||'')}"><strong>${esc(c.name)}</strong><div class="small sr-muted">${c.code?('کد '+esc(c.code)+' | '):''}${c.products_count} کالا</div></button>`).join('')||'<div class="sr-muted p-2">زیردسته‌ای وجود ندارد؛ محصولات همین دسته را ببینید.</div>'}
async function loadCategoryProducts(q=''){const cat=state.selectedCategories.at(-1);if(!cat)return;if(categoryProductAbort)categoryProductAbort.abort();categoryProductAbort=new AbortController();const r=await fetch(routes.categoryProducts.replace('__CATEGORY__',cat.id)+(q?('?q='+encodeURIComponent(q)):''),{signal:categoryProductAbort.signal});const data=await r.json();$('#categoryProductResults').innerHTML=(data.data||[]).map(p=>`<button type="button" class="list-group-item list-group-item-action product-select" data-id="${p.id}"><strong>${esc(p.name)}</strong><div class="small sr-muted">${esc(p.code||'بدون کد')} | ${esc(p.category||'بدون دسته')} | ${p.variants_count} تنوع ${p.is_active?'':' | غیرفعال'} ${p.sales_enabled?'':' | فروش غیرفعال'}</div></button>`).join('')||'<div class="p-2 sr-muted">محصولی یافت نشد.</div>'}
async function loadProductVariants(productId){const r=await fetch(routes.productVariants.replace('__PRODUCT__',productId));const data=await r.json();const product=data.product||{};state.selectedProducts[productId]=product;$('#variantCheckboxes').innerHTML=`<div class="mb-2"><strong>${esc(product.name||'محصول')}</strong><div class="small sr-muted">کد: ${esc(product.code||'—')}</div></div>`+(data.variants||[]).map(v=>{const key=String(v.id), checked=state.selectedVariants.has(key);return `<label class="d-block border rounded p-2 mb-1 ${checked?'bg-light':''}"><input type="checkbox" class="form-check-input ms-1 variant-pick" data-product-id="${productId}" data-product-name="${esc(product.name||'')}" data-variant='${esc(JSON.stringify(v))}' ${checked?'checked':''}> <strong>${esc(v.name||'تنوع اصلی')}</strong><div class="small sr-muted">طرح/مدل: ${esc(v.variety_name||'—')} | SKU: ${esc(v.sku||'—')} | موجودی: ${fmt(v.stock)} | خرید: ${fmt(v.buy_price)} | فروش: ${fmt(v.sell_price)} ${v.is_active?'':' | غیرفعال'} ${v.sales_enabled?'':' | فروش غیرفعال'}</div></label>`}).join('')+`<div class="sticky-bottom bg-white border-top pt-2 mt-2"><span id="variantSelectedCount">${state.selectedVariants.size}</span> تنوع انتخاب‌شده <button type="button" class="btn btn-primary btn-sm float-start" id="addPickedVariants">افزودن به برگشتی</button></div>`}
async function searchProducts(q){if(productAbort)productAbort.abort();if(q.length<2){$('#productResults').innerHTML='<div class="p-2 sr-muted">برای جستجو حداقل ۲ کاراکتر وارد کنید.</div>';return}productAbort=new AbortController();const r=await fetch(routes.productsSearch+'?q='+encodeURIComponent(q),{signal:productAbort.signal});const data=await r.json();$('#productResults').innerHTML=(data.results||[]).map(p=>`<button type="button" class="list-group-item list-group-item-action product-select" data-id="${p.id}"><strong>${esc(p.text)}</strong><div class="small sr-muted">${esc(p.category||'بدون دسته')} | SKU: ${esc(p.sku||'—')} | موجودی: ${fmt(p.stock)} ${p.is_active?'':' | غیرفعال'} ${p.sales_enabled?'':' | فروش غیرفعال'}</div></button>`).join('')||'<div class="p-2 sr-muted">نتیجه‌ای یافت نشد.</div>'}
function addSelectedVariants(){let added=0;state.selectedVariants.forEach(({variant,productId,productName})=>{if(state.items.some(i=>String(i.product_variant_id)===String(variant.id)))return;state.items.push({item_source:'existing_product',product_id:productId,product_variant_id:variant.id,product_name:productName,variant_name:variant.name,sku:variant.sku,barcode:variant.barcode,return_quantity:1,item_condition:'healthy',refund_unit_price:0,refund_amount:0,purchase_price:variant.buy_price,sell_price:variant.sell_price});added++;});renderItems();if(added)bootstrap.Modal.getInstance($('#sazehItemsModal'))?.hide();else alert('تنوع جدیدی برای افزودن وجود ندارد یا موارد تکراری هستند.')}

const np={categoryPath:[],selectedModels:new Set(),pickedVariants:new Set(),lastVariants:[],userTouchedVariants:false,showAllTags:false};
function npModels(){return init.modelLists||[]}
function npCategories(){return init.categories||[]}
function npChildren(parent){return npCategories().filter(c=>String(c.parent_id||'')===String(parent||''))}
function npCategoryById(id){return npCategories().find(c=>String(c.id)===String(id))}
function npSelectedCategory(){return np.categoryPath.length?npCategoryById(np.categoryPath[np.categoryPath.length-1]):null}
function npModelById(id){return npModels().find(m=>String(m.id)===String(id))}
function npInit(){if(!$('#npCategoryLevels'))return;const brand=$('#npModelBrand');if(brand&&brand.options.length<=1){[...new Set(npModels().map(m=>m.brand).filter(Boolean))].sort().forEach(b=>brand.insertAdjacentHTML('beforeend',`<option value="${esc(b)}">${esc(b)}</option>`))}npRenderCategoryLevels();npRenderModels();npRenderDesigns();npRenderPreview()}
function npRenderCategoryLevels(){const wrap=$('#npCategoryLevels');if(!wrap)return;wrap.innerHTML='';let parent=null;let level=0;while(true){const children=npChildren(parent);if(!children.length&&level>0)break;const selected=np.categoryPath[level]||'';const col=document.createElement('div');col.className='col-md-6 tree-level';col.innerHTML=`<label class="form-label">${level===0?'دسته اصلی':'زیر‌دسته '+level}</label><select class="form-select form-select-sm np-category-level" data-level="${level}"><option value="">انتخاب کنید</option>${children.map(c=>`<option value="${c.id}" data-code="${esc(c.code||'')}" ${String(c.id)===String(selected)?'selected':''}>${esc(c.name)} ${c.code?'('+esc(c.code)+')':''}</option>`).join('')}</select>`;wrap.appendChild(col);if(!selected)break;parent=selected;level++;if(level>8)break}npUpdateBreadcrumb()}
function npUpdateBreadcrumb(){const path=np.categoryPath.map(id=>npCategoryById(id)).filter(Boolean);$('#npCategoryBreadcrumb')&&($('#npCategoryBreadcrumb').textContent=path.length?path.map(c=>c.name).join(' > '):'دسته‌بندی انتخاب نشده است');const cat=path[path.length-1];const seq=toEnglishDigits($('#npSeqPreview')?.textContent||'0001');if(!cat){$('#npCodeHint')&&($('#npCodeHint').textContent='پس از انتخاب دسته‌بندی، کد کالا نمایش داده می‌شود.');$('#npProductCodePreview')&&($('#npProductCodePreview').textContent='—');$('#npVariantCodePreview')&&($('#npVariantCodePreview').textContent='—');return}$('#npCodeHint')&&($('#npCodeHint').textContent='کد کالا بر اساس دسته‌بندی نهایی ساخته می‌شود.');const code=(cat.code||'00').toString().padStart(2,'0').slice(0,2)+seq;$('#npSeqPreview')&&($('#npSeqPreview').textContent=toPersianDigits(seq));$('#npProductCodePreview')&&($('#npProductCodePreview').textContent=toPersianDigits(code));$('#npVariantCodePreview')&&($('#npVariantCodePreview').textContent=toPersianDigits(code+'MMMDD'))}
function syncNewProductLayout(){const grid=document.querySelector('.np-grid');if(!grid)return;grid.classList.toggle('has-models',$('#npUseModels')?.checked);grid.classList.toggle('has-designs',$('#npUseDesigns')?.checked)}
function npRenderModels(){syncNewProductLayout();const panel=$('#npModelPanel');if(!panel)return;panel.classList.toggle('d-none',!$('#npUseModels').checked);const brand=$('#npModelBrand').value, q=($('#npModelSearch').value||'').toLowerCase();const list=npModels().filter(m=>(!brand||m.brand===brand)&&(!q||String(m.model_name+' '+m.code+' '+m.brand).toLowerCase().includes(q)));$('#npModelList').innerHTML=list.map(m=>`<label class="d-block border rounded p-2 mb-1"><input type="checkbox" class="form-check-input ms-1 np-model-check" value="${m.id}" ${np.selectedModels.has(String(m.id))?'checked':''}> <strong>${esc(m.model_name||'')}</strong><div class="small sr-muted">${esc(m.brand||'—')} | کد: ${esc(toPersianDigits(m.code||'—'))}</div></label>`).join('')||'<div class="sr-muted small">مدلی برای این فیلتر وجود ندارد.</div>';$('#npSelectedModelCount').textContent=np.selectedModels.size;{const models=[...np.selectedModels].map(id=>npModelById(id)).filter(Boolean);const visible=np.showAllTags?models:models.slice(0,6);$('#npModelTags').innerHTML=visible.map(m=>`<span class="picker-tag">${esc(m.brand)} / ${esc(m.model_name)} (${esc(toPersianDigits(m.code||'—'))})</span>`).join('')+(models.length>6&&!np.showAllTags?`<button type="button" class="btn btn-link btn-sm p-0" id="npShowAllModelTags">+ ${toPersianDigits(models.length-6)} مدل دیگر</button>`:'')}}
function npRenderDesigns(){syncNewProductLayout();const on=$('#npUseDesigns')?.checked;$('#npDesignPanel')?.classList.toggle('d-none',!on);const wrap=$('#npDesignRows');if(!wrap)return;if(!on){wrap.innerHTML='';return}let count=Math.max(1,Math.min(99,Number($('#npDesignCount').value||1)));$('#npDesignCount').value=count;const old=$$('.np-design-name').map(i=>i.value);wrap.innerHTML='';for(let i=1;i<=count;i++){wrap.insertAdjacentHTML('beforeend',`<div class="design-note-item"><span class="badge bg-light text-dark">طرح ${i}</span><input class="form-control form-control-sm np-design-name np-field" data-index="${i}" value="${esc(old[i-1]||'')}" placeholder="مثلاً مشکی"></div>`)}}
function npDesigns(){return $('#npUseDesigns')?.checked?$$('.np-design-name').map((i,idx)=>({index:idx+1,name:i.value.trim()})).filter(d=>d.name):[]}
function npSyncPrice(id){const key=id==='npPurchase'?'purchase':id==='npSell'?'sell':'refund';const value=moneyToInteger($('#'+id)?.value||'');state.newProduct.prices[key]=value;const input=$('#'+id);if(input)input.value=value===null?'':fmt(value)}
function npPrice(id){const key=id==='npPurchase'?'purchase':id==='npSell'?'sell':'refund';return state.newProduct.prices[key]}
function npVariantCombos(){if(!npSelectedCategory())return[];const useM=$('#npUseModels')?.checked,useD=$('#npUseDesigns')?.checked;const models=useM?[...np.selectedModels].map(id=>npModelById(id)).filter(Boolean):[null];const designs=useD?npDesigns():[{index:0,name:''}];const base=($('#npName')?.value||'کالای جدید').trim();const cat=npSelectedCategory();const seq=$('#npSeqPreview')?.textContent||'0001';const productCode=((cat?.code||'00').toString().padStart(2,'0').slice(0,2)+toEnglishDigits(seq));let rows=[];models.forEach(m=>designs.forEach(d=>{const key='model:'+(m?.id||'none')+'|design:'+(d.index||'none');const modelCode=String(m?.code||'000').replace(/\D/g,'').padStart(3,'0').slice(0,3);const designCode=String(d.index||0).padStart(2,'0');rows.push({key,model:m,design:d,display_name:[base,m?.model_name,d.name].filter(Boolean).join(' / '),preview_code:productCode+modelCode+designCode})}));return rows.length?rows:[]}
function npValidate(){const errs=[];const setErr=(sel,msg)=>{const el=$(sel);if(el)el.textContent=msg||'';if(msg)errs.push(msg)};setErr('#npCategoryError',npSelectedCategory()?'':'دسته‌بندی نهایی کالا را انتخاب کنید.');if($('#npUseModels')?.checked&&np.selectedModels.size<1)errs.push('حداقل یک مدل انتخاب کنید.');if($('#npUseDesigns')?.checked){const c=Number($('#npDesignCount').value||0), d=npDesigns();setErr('#npDesignError',(c<1||d.length!==c)?'نام همه طرح‌ها را کامل کنید.':'')}else setErr('#npDesignError','');['npPurchase','npSell','npRefund'].forEach(id=>{const value=npPrice(id);const required=id==='npRefund';const msg=(value===null||value<0||(required&&value<1))?'قیمت معتبر وارد کنید.':'';setErr(`[data-price-error="${id}"]`,msg)});const selected=npVariantCombos().filter(v=>np.pickedVariants.has(v.key)).length;setErr('#npVariantError',selected<1?'حداقل یک تنوع باید انتخاب شود.':'');if(!$('#npName')?.value.trim())errs.push('نام کالا الزامی است.');$('#npErrors')&&($('#npErrors').innerHTML='');$('#addNewProductRow')&&($('#addNewProductRow').disabled=errs.length>0);return errs.length===0}
function npRenderPreview(){const rows=npVariantCombos();const currentKeys=new Set(rows.map(r=>r.key));[...np.pickedVariants].forEach(k=>{if(!currentKeys.has(k))np.pickedVariants.delete(k)});if(!np.pickedVariants.size&&rows.length&&!np.userTouchedVariants)rows.forEach(r=>np.pickedVariants.add(r.key));np.lastVariants=rows;const picked=rows.filter(r=>np.pickedVariants.has(r.key));$('#npVariantPreview')&&($('#npVariantPreview').innerHTML=rows.length?rows.map(r=>`<div class="sr-variant-preview__row"><div class="sr-variant-preview__cell" data-label="انتخاب"><input type="checkbox" class="form-check-input np-variant-check" value="${r.key}" ${np.pickedVariants.has(r.key)?'checked':''}></div><div class="sr-variant-preview__cell sr-variant-preview__name" data-label="نام تنوع">${esc(r.display_name)}</div><div class="sr-variant-preview__cell" data-label="مدل">${esc(r.model?((r.model.brand||'')+' '+(r.model.model_name||'')):'—')}</div><div class="sr-variant-preview__cell" data-label="طرح">${esc(r.design.name||'—')}</div><div class="sr-variant-preview__cell sr-variant-preview__code" data-label="کد نمونه">${esc(toPersianDigits(r.preview_code))}</div><div class="sr-variant-preview__cell sr-variant-preview__money" data-label="خرید">${fmt(npPrice('npPurchase'))||'—'}</div><div class="sr-variant-preview__cell sr-variant-preview__money" data-label="فروش">${fmt(npPrice('npSell'))||'—'}</div><div class="sr-variant-preview__cell sr-variant-preview__money" data-label="برگشتی">${fmt(npPrice('npRefund'))||'—'}</div></div>`).join(''):`<div class="np-empty-state">برای پیش‌نمایش تنوع‌ها، ابتدا دسته‌بندی و ساختار کالا را کامل کنید.</div>`);['npTotalVariants','npPickedVariants','npFooterSelected'].forEach(id=>$('#'+id)&&($('#'+id).textContent=id==='npTotalVariants'?rows.length:picked.length));$('#npUnpickedVariants')&&($('#npUnpickedVariants').textContent=Math.max(0,rows.length-picked.length));$('#npFooterRefund')&&($('#npFooterRefund').textContent=fmt(npPrice('npRefund'))||'۰');$('#addNewProductRow')&&($('#addNewProductRow').textContent='افزودن '+toPersianDigits(picked.length)+' تنوع به سند');npValidate()}
function npPayload(){const uuid=crypto.randomUUID?crypto.randomUUID():('tmp-'+Date.now()+'-'+Math.random());const catPath=np.categoryPath.map(id=>npCategoryById(id)).filter(Boolean).map(c=>({id:c.id,name:c.name,code:c.code}));const selectedRows=np.lastVariants.filter(r=>np.pickedVariants.has(r.key));return {schema_version:2,temporary_product_uuid:uuid,name:$('#npName').value.trim(),product_name:$('#npName').value.trim(),category_id:npSelectedCategory()?.id,category_path_snapshot:catPath,is_sellable:$('#npSales').value==='1',sales_enabled:$('#npSales').value==='1',unit:$('#npUnit').value||'عدد',use_models:$('#npUseModels').checked,model_brand_group:$('#npModelBrand').value||'',model_list_ids:[...np.selectedModels].map(Number),selected_models:[...np.selectedModels].map(id=>npModelById(id)).filter(Boolean).map(m=>({id:m.id,brand:m.brand,name:m.model_name,code:m.code})),use_designs:$('#npUseDesigns').checked,designs:npDesigns(),purchase_price:npPrice('npPurchase')??0,sell_price:npPrice('npSell')??0,refund_unit_price_default:npPrice('npRefund')??0,selected_variants:selectedRows.map(r=>({temporary_variant_uuid:crypto.randomUUID?crypto.randomUUID():('tmpv-'+Date.now()+Math.random()),model_list_id:r.model?.id||null,design_index:r.design.index||0,display_name:r.display_name,preview_code:r.preview_code}))}}
function npAddRows(){if(!npValidate())return;const payload=npPayload();payload.selected_variants.forEach(v=>state.items.push({item_source:'new_product',product_name:payload.name,variant_name:v.display_name,sku:v.preview_code,return_quantity:1,item_condition:'healthy',refund_unit_price:payload.refund_unit_price_default,refund_amount:payload.refund_unit_price_default,purchase_price:payload.purchase_price,sell_price:payload.sell_price,new_product_payload:{...payload,variant_name:v.display_name,temporary_variant_uuid:v.temporary_variant_uuid,model_list_id:v.model_list_id,design_index:v.design_index,selected_variants:[v]}}));renderItems();bootstrap.Modal.getInstance($('#sazehItemsModal'))?.hide()}
npInit();document.addEventListener('shown.bs.tab',e=>{if(e.target?.dataset?.bsTarget==='#newProductTab')npInit()});document.addEventListener('change',e=>{if(e.target.classList.contains('np-category-level')){const lvl=Number(e.target.dataset.level);np.categoryPath=np.categoryPath.slice(0,lvl);if(e.target.value)np.categoryPath.push(e.target.value);npRenderCategoryLevels();np.pickedVariants.clear();np.userTouchedVariants=false;npRenderPreview()}if(e.target.id==='npUseModels'||e.target.id==='npUseDesigns'){npRenderModels();npRenderDesigns();npRenderPreview()}if(e.target.id==='npModelBrand'){if(np.selectedModels.size&&!confirm('با تغییر برند، مدل‌های انتخاب‌شده پاک شوند؟'))return;np.selectedModels.clear();np.pickedVariants.clear();np.userTouchedVariants=false;npRenderModels();npRenderPreview()}if(e.target.classList.contains('np-model-check')){e.target.checked?np.selectedModels.add(String(e.target.value)):np.selectedModels.delete(String(e.target.value));npRenderModels();npRenderPreview()}if(e.target.classList.contains('np-variant-check')){np.userTouchedVariants=true;e.target.checked?np.pickedVariants.add(e.target.value):np.pickedVariants.delete(e.target.value);npRenderPreview()}});document.addEventListener('input',e=>{if(e.target.classList.contains('np-money')){npSyncPrice(e.target.id)}if(e.target.classList.contains('np-field')||e.target.classList.contains('np-design-name')){if(e.target.id==='npDesignCount')npRenderDesigns();npRenderModels();npRenderPreview()}});$('#npSelectFilteredModels')&&($('#npSelectFilteredModels').onclick=()=>{$$('.np-model-check').forEach(cb=>np.selectedModels.add(String(cb.value)));np.pickedVariants.clear();np.userTouchedVariants=false;npRenderModels();npRenderPreview()});document.addEventListener('click',e=>{if(e.target.id==='npShowAllModelTags'){np.showAllTags=true;npRenderModels()}});$('#npClearModels')&&($('#npClearModels').onclick=()=>{np.selectedModels.clear();np.pickedVariants.clear();np.userTouchedVariants=false;npRenderModels();npRenderPreview()});$('#npQuickCategory')&&($('#npQuickCategory').onclick=async()=>{const name=prompt('نام دسته‌بندی جدید');if(!name)return;alert('افزودن سریع از Route '+routes.categoriesQuickStore+' و Permission واقعی آن استفاده می‌کند؛ در این نسخه برای جلوگیری از تغییر ناخواسته DB از مودال draft اجرا نمی‌شود.')});$('#npQuickModel')&&($('#npQuickModel').onclick=()=>alert('افزودن سریع مدل از Route '+routes.modelListsQuickStore+' و Permission واقعی مدل‌لیست استفاده می‌کند.'));$('#addNewProductRow')&&($('#addNewProductRow').onclick=npAddRows);$$('[name=source_choice]').forEach(r=>r.addEventListener('change',e=>setSource(e.target.value)));$('#customerSearch').addEventListener('focus',()=>searchCustomers(''));$('#customerSearch').addEventListener('input',e=>{clearTimeout(customerTimer);customerTimer=setTimeout(()=>searchCustomers(e.target.value),280)});$('#customerSearch').addEventListener('keydown',e=>{const rows=$$('#customerResults .sr-result');if(e.key==='Escape'){closeCustomerDropdown();return}if(!rows.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();customerActive=(customerActive+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;rows.forEach((r,i)=>r.classList.toggle('active',i===customerActive));rows[customerActive].scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&customerActive>=0){e.preventDefault();selectCustomer(rows[customerActive]);}});window.addEventListener('resize',positionCustomerDropdown);window.addEventListener('scroll',positionCustomerDropdown,true);document.addEventListener('click',e=>{const clear=e.target.closest('#clearCustomer');if(clear){setSelectedCustomer(null);return}const el=e.target.closest('.sr-result');if(el){selectCustomer(el);return}if(!e.target.closest('#customerSearch')&&!e.target.closest('#customerResults'))closeCustomerDropdown()});$('#refreshCustomers').onclick=()=>{setSelectedCustomer(null);searchCustomers('')};$('#returnReason').addEventListener('change',e=>$('#otherReasonNote')?.classList.toggle('d-none',e.target.value!=='other'));function renderInvoiceSummary(){const opt=$('#invoiceSelect')?.selectedOptions?.[0];$('#invoiceSummary').textContent=opt?.dataset?.summary||''}
$('#invoiceSelect').addEventListener('change',e=>{$('#invoiceId').value=e.target.value;state.invoice=e.target.value;state.items=[];renderItems();renderInvoiceSummary()});$('#openAddItem').onclick=()=>{if(state.type==='internal_invoice'){loadInvoiceItems().then(()=>new bootstrap.Modal($('#internalItemsModal')).show())}else{loadCategories(null);new bootstrap.Modal($('#sazehItemsModal')).show()}};$('#addSelectedInvoiceItems').onclick=()=>{$$('.invoice-pick:checked').forEach(cb=>{const it=JSON.parse(cb.dataset.item);if(state.items.some(x=>x.invoice_item_id===it.invoice_item_id))return;state.items.push({item_source:'invoice_item',invoice_item_id:it.invoice_item_id,product_id:it.product_id,product_variant_id:it.variant_id,product_name:it.product_name,variant_name:it.variant_name,sku:it.sku,barcode:it.barcode,sold_quantity:it.quantity,previously_returned:it.previously_returned,returnable:it.returnable,return_quantity:1,item_condition:'healthy',refund_unit_price:it.unit_price,refund_amount:it.unit_price})});renderItems();bootstrap.Modal.getInstance($('#internalItemsModal')).hide()};$('#invoiceItemFilter').addEventListener('input',e=>{$$('#invoiceItemsBody tr').forEach(tr=>tr.classList.toggle('d-none',!tr.dataset.text.includes(e.target.value)))});$('#categoryResults')?.addEventListener('click',e=>{const el=e.target.closest('.cat-pick');if(!el)return;state.selectedCategories.push({id:el.dataset.id,name:el.dataset.name});$('#categoryPath').textContent=state.selectedCategories.map(c=>c.name).join(' > ');loadCategories(el.dataset.id);loadCategoryProducts();$('#variantCheckboxes').textContent='محصول را انتخاب کنید.'});$('#categoryProductSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>loadCategoryProducts(e.target.value),300)});$('#productSearch')?.addEventListener('input',e=>{clearTimeout(productTimer);productTimer=setTimeout(()=>searchProducts(e.target.value),300)});document.addEventListener('click',e=>{const ps=e.target.closest('.product-select');if(ps)loadProductVariants(ps.dataset.id);if(e.target.id==='addPickedVariants')addSelectedVariants();if(e.target.classList.contains('rm')){state.items.splice(Number(e.target.dataset.i),1);renderItems()}});document.addEventListener('change',e=>{if(e.target.classList.contains('variant-pick')){const v=JSON.parse(e.target.dataset.variant), key=String(v.id);e.target.checked?state.selectedVariants.set(key,{variant:v,productId:e.target.dataset.productId,productName:e.target.dataset.productName}):state.selectedVariants.delete(key);$('#variantSelectedCount')&&($('#variantSelectedCount').textContent=state.selectedVariants.size)}});document.addEventListener('input',e=>{if(e.target.classList.contains('qty')){state.items[Number(e.target.dataset.i)].return_quantity=Number(e.target.value);renderItems()}if(e.target.classList.contains('price')){state.items[Number(e.target.dataset.i)].refund_unit_price=rawNumber(e.target.value);renderItems()}});$('#defaultWarehouse').addEventListener('change',e=>{state.defaultDestinationWarehouseId=e.target.value;summary()});$('#clearForm').onclick=()=>{if(confirm('فرم پاک شود؟')){state.items=[];renderItems()}};$('#applyButton').onclick=e=>{if(!confirm('ثبت نهایی موجودی و بستانکاری مشتری را تغییر می‌دهد. ادامه می‌دهید؟'))e.preventDefault()};syncExternalDateDisplay();$('#externalInvoiceDateFa')?.addEventListener('input',e=>syncExternalDateFromVisible(false));$('#salesReturnForm')?.addEventListener('submit',e=>{if(!state.defaultDestinationWarehouseId){e.preventDefault();$('#defaultWarehouse')?.focus();alert('برای ادامه یک انبار مقصد واحد انتخاب کنید.');return}if(state.type==='sazeh_hesab'&&!syncExternalDateFromVisible(true)){e.preventDefault();$('#externalInvoiceDateFa')?.focus()}});syncSource();if(init.customerId)loadInvoices();renderItems();
})();
</script>
